-- Orava Certificate Store · 0004 · automatic reading (Phase 3)
-- Run with `pnpm db:migrate`.

-- What was read from the file, kept for search (Phase 4) and so the admin can look back at it
alter table certificates add column if not exists ocr_text text not null default '';
-- How the certificate was read: confidence, rotation, fields found / to check, time taken
alter table certificates add column if not exists extraction jsonb;
-- Saved automatically with fields to check: shown with a "Check" badge until the admin saves it
alter table certificates add column if not exists needs_review boolean not null default false;
create index if not exists certificates_review_idx on certificates (needs_review)
  where deleted_at is null and needs_review;

-- Reading hints tuned on the 4 sample certificates. Only types the admin has not edited yet
-- (still version 1) are updated; edited types keep the admin's own settings.
update certificate_types set fields = '[{"key": "report_no", "label": "Report No", "kind": "text", "required": true, "showInList": true, "filterable": false, "role": "report_no", "hints": {"labels": ["Report No", "Report Number"], "pattern": "re:[A-Z]{1,4}\\d{8}"}}, {"key": "date", "label": "Date", "kind": "date", "required": false, "showInList": true, "filterable": false, "role": "report_date", "hints": {"labels": ["Date"], "pattern": "date", "cleanup": ["parse_date"]}}, {"key": "weight", "label": "Weight (ct)", "kind": "carat", "required": false, "showInList": true, "filterable": false, "role": "weight", "hints": {"labels": ["Weight", "Carat Weight"], "pattern": "carat"}}, {"key": "shape", "label": "Shape", "kind": "text", "required": false, "showInList": false, "filterable": true, "hints": {"labels": ["Shape"]}}, {"key": "cut", "label": "Cut", "kind": "text", "required": false, "showInList": false, "filterable": true, "hints": {"labels": ["Cut"]}}, {"key": "measurements", "label": "Measurements (mm)", "kind": "text", "required": false, "showInList": false, "filterable": false, "hints": {"labels": ["Measurements", "Dimensions"], "pattern": "mm_size"}}, {"key": "color", "label": "Color", "kind": "text", "required": false, "showInList": false, "filterable": true, "hints": {"labels": ["Color", "Colour"]}}, {"key": "origin", "label": "Origin", "kind": "text", "required": false, "showInList": false, "filterable": true, "hints": {"labels": ["Origin", "Provenance"]}}, {"key": "identification", "label": "Identification", "kind": "text", "required": true, "showInList": true, "filterable": true, "role": "identification", "hints": {"labels": ["Identification", "Species"]}}, {"key": "comments", "label": "Comments", "kind": "longtext", "required": false, "showInList": false, "filterable": false, "hints": {"labels": ["Comments and Opinions", "Comments", "Comment"]}}, {"key": "instruments", "label": "Instruments used", "kind": "multiselect", "required": false, "showInList": false, "filterable": false, "options": ["Microscope", "FTIR", "EDXRF", "UV-Vis-NIR", "LIBS", "DFI", "Raman", "Refractometer", "Spectroscope", "Polariscope", "UV lamp", "UV-Vis"], "hints": {"labels": ["Instruments Used", "Instruments"]}}]'::jsonb, updated_at = now()
  where slug = 'aigs-gemstone-identification-report' and version = 1;
